#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    pad: u32,
    x_min: f32,
    y_min: f32,
    dx: f32,
    dy: f32,
}

struct Input {
    width: u32,
    height: u32,
    limit: u32,
    x_min: f64,
    x_max: f64,
    y_min: f64,
    y_max: f64,
}

fn parse_input(text: &str) -> Result<Input, String> {
    let t: Vec<&str> = text.split_whitespace().collect();
    if t.len() < 7 {
        return Err("expected 7 values".into());
    }
    let int = |s: &str| s.parse::<u32>().map_err(|e| format!("{s}: {e}"));
    let flt = |s: &str| s.parse::<f64>().map_err(|e| format!("{s}: {e}"));
    Ok(Input {
        width: int(t[0])?,
        height: int(t[1])?,
        limit: int(t[2])?,
        x_min: flt(t[3])?,
        x_max: flt(t[4])?,
        y_min: flt(t[5])?,
        y_max: flt(t[6])?,
    })
}

fn compute(inp: &Input) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::default());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        force_fallback_adapter: false,
        compatible_surface: None,
    }))
    .map_err(|e| format!("no adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| format!("no device: {e}"))?;

    let count = inp.width as usize * inp.height as usize;
    let size = (count * 4) as u64;
    let params = Params {
        width: inp.width,
        height: inp.height,
        limit: inp.limit,
        pad: 0,
        x_min: inp.x_min as f32,
        y_min: inp.y_min as f32,
        dx: ((inp.x_max - inp.x_min) / inp.width as f64) as f32,
        dy: ((inp.y_max - inp.y_min) / inp.height as f64) as f32,
    };
    let ubuf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::bytes_of(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let out = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });
    let read = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: None,
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: None,
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let bind = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: None,
        layout: &pipeline.get_bind_group_layout(0),
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: ubuf.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 1, resource: out.as_entire_binding() },
        ],
    });
    let mut enc = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
    {
        let mut pass = enc.begin_compute_pass(&wgpu::ComputePassDescriptor::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind, &[]);
        pass.dispatch_workgroups(inp.width.div_ceil(8), inp.height.div_ceil(8), 1);
    }
    enc.copy_buffer_to_buffer(&out, 0, &read, 0, size);
    queue.submit(Some(enc.finish()));

    let slice = read.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("poll: {e}"))?;
    rx.recv()
        .map_err(|e| e.to_string())?
        .map_err(|e| format!("map: {e}"))?;
    let data = slice.get_mapped_range();
    let times: Vec<u32> = bytemuck::cast_slice(&data).to_vec();
    drop(data);
    read.unmap();
    Ok(times)
}

fn run() -> Result<(), String> {
    let path = std::env::args().nth(1).ok_or("missing input path")?;
    let text = std::fs::read_to_string(&path).map_err(|e| format!("{path}: {e}"))?;
    let inp = parse_input(&text)?;
